import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates credit note for issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Partial refund', date: '2024-01-20' }, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'CN-2024-0001');
  assert.equal(r2.value.invoiceNumber, 'INV-2024-0001');
  assert.equal(r2.value.customerId, 'C-002');
  assert.equal(r2.value.amount, 5000);
  assert.equal(r2.value.reason, 'Partial refund');
  assert.equal(r2.value.date, '2024-01-20');
});

test('createCreditNote works for partially_paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2024-01-20' }).value;
  const r2 = createCreditNote(partial, { amount: 5000, reason: 'Partial refund', date: '2024-01-25' }, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, undefined);
  assert.equal(r2.value.amount, 5000);
});

test('createCreditNote works for paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const paid = recordPayment(issued, { amount: 51425, date: '2024-01-20' }).value;
  const r2 = createCreditNote(paid, { amount: 10000, reason: 'Full refund', date: '2024-01-25' }, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 10000);
});

test('createCreditNote returns NOT_ISSUED for draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const r2 = createCreditNote(r.value, { amount: 5000, reason: 'Partial refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote returns DATE_INVALID for invalid date', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Partial refund', date: 'invalid-date' }, []);
  assert.deepEqual(r2, { ok: false, error: 'DATE_INVALID' });
});

test('createCreditNote returns AMOUNT_INVALID for zero amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: 0, reason: 'Partial refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote returns AMOUNT_INVALID for negative amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: -1000, reason: 'Partial refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote returns AMOUNT_INVALID for non-integer amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: 5000.5, reason: 'Partial refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote returns CREDIT_TOO_HIGH if amount exceeds invoice total', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // Total: 51425
  const r2 = createCreditNote(issued, { amount: 51426, reason: 'Partial refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote with amount equal to invoice total', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // Total: 51425
  const r2 = createCreditNote(issued, { amount: 51425, reason: 'Full refund', date: '2024-01-20' }, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 51425);
});

test('createCreditNote numbers sequentially within a year', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;

  const r2 = createCreditNote(issued, { amount: 5000, reason: 'First refund', date: '2024-01-20' }, []);
  assert.equal(r2.value.number, 'CN-2024-0001');

  const r3 = createCreditNote(issued, { amount: 5000, reason: 'Second refund', date: '2024-01-25' }, ['CN-2024-0001']);
  assert.equal(r3.value.number, 'CN-2024-0002');

  const r4 = createCreditNote(issued, { amount: 5000, reason: 'Third refund', date: '2024-02-01' }, ['CN-2024-0001', 'CN-2024-0002']);
  assert.equal(r4.value.number, 'CN-2024-0003');
});

test('createCreditNote resets counter for new year', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;

  // 2024 credit notes
  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2024-12-20' }, []);
  assert.equal(r2.value.number, 'CN-2024-0001');

  // 2025 credit notes should reset to 0001
  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued3 = issueInvoice(r3.value, ['INV-2025-0001']).value;
  const r4 = createCreditNote(issued3, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, ['CN-2024-0001', 'INV-2025-0001']);
  assert.equal(r4.value.number, 'CN-2025-0001');
});

test('createCreditNote ignores invoice numbers when counting', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;

  // Even with many invoice numbers, credit notes start at 0001
  const existingNumbers = [
    'INV-2024-0001',
    'INV-2024-0002',
    'INV-2024-0003',
    'INV-2024-0004',
    'INV-2024-0005'
  ];

  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2024-01-20' }, existingNumbers);
  assert.equal(r2.value.number, 'CN-2024-0001');
});

test('createCreditNote preserves invoice number', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2024-01-20' }, []);

  assert.equal(r2.value.invoiceNumber, 'INV-2024-0001');
});

test('createCreditNote zero-pads counter to 4 digits', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;

  // Create 100 credit notes to get to a 4-digit number
  const existingNumbers = Array.from({ length: 100 }, (_, i) => `CN-2024-${String(i + 1).padStart(4, '0')}`);

  const r2 = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2024-12-20' }, existingNumbers);
  assert.equal(r2.value.number, 'CN-2024-0101');
});

test('createCreditNote with invoice that has discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // Subtotal: 42500, Discount: 4250, VAT: 8032, Total: 46282

  const r2 = createCreditNote(issued, { amount: 46282, reason: 'Full refund', date: '2024-01-20' }, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 46282);
});

test('createCreditNote with invoice that has voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const r2 = require('../src/invoices.js').applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const issued = issueInvoice(r2.value, []).value;
  // Total without voucher: 51425, with voucher: 46425

  const r3 = createCreditNote(issued, { amount: 46425, reason: 'Full refund', date: '2024-01-20' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.amount, 46425);
});

test('createCreditNote credit note amount can exceed invoice total should fail', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // Total for 1 design hour: 8500 + 1785 (VAT) = 10285

  const r2 = createCreditNote(issued, { amount: 10286, reason: 'Refund', date: '2024-01-20' }, []);
  assert.deepEqual(r2, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote with VAT-exempt product', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // WORKSHOP-DAY: 60000 cents, no VAT, total = 60000

  const r2 = createCreditNote(issued, { amount: 60000, reason: 'Full refund', date: '2024-01-20' }, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 60000);
});

test('createCreditNote with multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, discountPercent: 0 }
    ]
  });

  const issued = issueInvoice(r.value, []).value;
  // DES-HOUR: 42500, STICKER: 5000, Subtotal: 47500
  // VAT on DES-HOUR (21%): 8925, VAT on STICKER (21%): 1050
  // Total VAT: 9975, Total: 57475

  const r2 = createCreditNote(issued, { amount: 57475, reason: 'Full refund', date: '2024-01-20' }, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 57475);
});

